impl GoodPracticesEngine {
    /// MCCPE: attempting to call a property or event as a function.
    pub(crate) fn check_mccpe(&self, tree: &tree_sitter::Tree, source: &str) -> Vec<Diagnostic> {
        if !self.is_check_enabled("MCCPE") {
            return Vec::new();
        }

