use tree_sitter::Parser;

fn dump(node: tree_sitter::Node, source: &str, depth: usize) {
    let indent = "  ".repeat(depth);
    let text = &source[node.start_byte()..node.end_byte()];
    let text_short: String = text.chars().take(50).collect();
    println!(
        "{indent}{} [{}..{}] {:?}",
        node.kind(),
        node.start_byte(),
        node.end_byte(),
        text_short.replace('
', "\n")
    );
    let mut cursor = node.walk();
    for child in node.children(&mut cursor) {
        dump(child, source, depth + 1);
    }
}

fn main() {
    let samples = [
        // app designer method call via dot
        "classdef MyApp < matlab.apps.AppBase
    methods
        function doIt(app)
            app.updatePlot();
            updatePlot(app, 1);
            updatePlot();
            disp('hi');
        end
    end
end
",
        // app designer property assignment
        "classdef MyApp < matlab.apps.AppBase
    properties
        Value
        Count
    end
    methods
        function doIt(app)
            Value = 5;
            temp = 1;
            y = Count;
            z = app.Value;
        end
    end
end
",
        // value class mutate no output
        "classdef ValClass
    properties
        X
    end
    methods
        function obj = mutate(obj)
            obj.X = 5;
        end
        function badMutate(obj)
            obj.X = 5;
        end
    end
end
",
        // set method in handle class with output
        "classdef HClass < handle
    properties
        X
    end
    methods
        function set.X(obj, val)
            obj.X = val;
        end
        function obj = set.Y(obj, val)
            obj.Y = val;
        end
    end
end
",
        // nested constructor call
        "function y = foo()
    y = Foo(Foo(1));
end
",
        // constant property dot chain
        "classdef MyClass
    properties (Constant)
        C = 42
    end
    methods
        function go(obj)
            x = MyClass.C.foo;
            y = MyClass.C;
        end
    end
end
",
        // validate function
        "function validateFoo(y, x)
    y = 5;
    disp(x);
end
",
        // get. method
        "classdef G
    properties (Dependent)
        Y
    end
    methods
        function v = get.Y(obj)
            v = obj.Y;
        end
    end
end
",
    ];

    for (i, src) in samples.iter().enumerate() {
        println!("================ SAMPLE {i} ================");
        let mut parser = Parser::new();
        parser
            .set_language(&tree_sitter_matlab::LANGUAGE.into())
            .expect("lang");
        let tree = parser.parse(src, None).expect("parse");
        dump(tree.root_node(), src, 0);
    }
}

use tree_sitter::Parser;

fn dump(node: tree_sitter::Node, source: &str, depth: usize) {
    let indent = "  ".repeat(depth);
    let text = &source[node.start_byte()..node.end_byte()];
    let text_short: String = text.chars().take(50).collect();
    let obj = node
        .child_by_field_name("object")
        .map(|o| node_text(o, source).to_string())
        .unwrap_or_default();
    let fld = node
        .child_by_field_name("field")
        .map(|o| node_text(o, source).to_string())
        .unwrap_or_default();
    println!(
        "{indent}{} [{}..{}] {:?} object={:?} field={:?}",
        node.kind(),
        node.start_byte(),
        node.end_byte(),
        text_short.replace('\n', "\\n"),
        obj,
        fld
    );
    let mut cursor = node.walk();
    for child in node.children(&mut cursor) {
        dump(child, source, depth + 1);
    }
}

fn node_text<'a>(node: tree_sitter::Node, source: &'a str) -> &'a str {
    &source[node.start_byte()..node.end_byte()]
}

fn main() {
    let samples = [
        // chained field expression field names
        "classdef MyClass\n    properties (Constant)\n        C = 42\n    end\n    methods\n        function go(obj)\n            x = MyClass.C.foo.bar;\n            y = obj.C;\n            z = app.Value;\n        end\n    end\nend\n",
        // call via dot
        "classdef MyApp < matlab.apps.AppBase\n    methods\n        function doIt(app)\n            app.updatePlot(1);\n        end\n    end\nend\n",
        // parfor reduction with multiple patterns
        "acc = 0;\nparfor i = 1:10\n    acc = acc + i;\n    tot = tot + i;\nend\ndisp(acc);\n",
        // global declaration
        "function f()\n    global g\n    parfor i = 1:10\n        g = g + i;\n    end\nend\n",
        // assignment to function_call lhs (indexing)
        "x(1) = 5;\ny.foo = 3;\n",
        // self = pattern in value class
        "classdef V\n    properties\n        X\n    end\n    methods\n        function bad(self)\n            self.X = 1;\n        end\n    end\nend\n",
        // nested function with loop index assignment
        "function outer()\n    for k = 1:5\n        z = k;\n    end\n    function inner()\n        k = 3;\n    end\nend\n",
        // empty arguments call
        "foo();\nfoo(1);\n",
    ];

    for (i, src) in samples.iter().enumerate() {
        println!("================ SAMPLE {i} ================");
        let mut parser = Parser::new();
        parser
            .set_language(&tree_sitter_matlab::LANGUAGE.into())
            .expect("lang");
        let tree = parser.parse(src, None).expect("parse");
        dump(tree.root_node(), src, 0);
    }
}

