pub(crate) fn check_parfor_reduction(&self, tree: &tree_sitter::Tree, source: &str) -> Vec<Diagnostic> {
    let any = self.is_check_enabled("PFRIN") || self.is_check_enabled("PFRUS");
    if !any { return Vec::new(); }
    let sym = SymbolTable::build(tree, source);
    let mut diagnostics = Vec::new();
    for parfor in collect_parfor_nodes(tree.root_node(), source) {
        let body = find_child_of_kind(parfor, "block");
        let Some(body) = body else { continue };
        let mut seen = HashSet::new();
        let mut assignments = Vec::new();
        collect_nodes_of_kind(body, "assignment", &mut assignments);
        for assign in assignments {
            let lhs = assign.child_by_field_name("left")?;
            if lhs.kind() != "identifier" { continue; }
            let name = node_text(lhs, source).to_string();
            // op-assign pattern: rhs is binary_operator whose left is identifier name
            let rhs = assign.child_by_field_name("right");
            let is_reduction = match rhs {
                Some(r) if r.kind() == "binary_operator" => {
                    r.child_by_field_name("left").or_else(|| r.child(0))
                        .map(|l| l.kind() == "identifier" && node_text(l, source) == name)
                        .unwrap_or(false)
                }
                _ => false,
            };
            if !is_reduction || !seen.insert(name.clone()) { continue; }
            // PFRIN
            if self.is_check_enabled("PFRIN") && !is_defined_before_parfor(&sym, &name, parfor.start_byte()) {
                push diag PFRIN "The reduction variable {name} might not be set before the PARFOR loop." on lhs
            }
            // PFRUS
            if self.is_check_enabled("PFRUS") {
                let uses = uses_after_parfor(&sym, &name, parfor.end_byte(), tree, false);
                if uses.is_empty() {
                    push diag PFRUS "The reduction variable {name} might not be used after the PARFOR loop." on lhs
                }
            }
        }
    }
    diagnostics
}
```

