/// Find the nearest enclosing `class_definition` of a node.
pub(crate) fn enclosing_class_definition(node: Node) -> Option<Node> {
    let mut current = node.parent();
    while let Some(p) = current {
        if p.kind() == "class_definition" {
            return Some(p);
        }
        if p.kind() == "source_file" {
            return None;
        }
        current = p.parent();
    }
    None
}
