pub(crate) fn collect_loop_index_vars(node: Node, source: &str) -> std::collections::HashSet<String> {
    let mut out = std::collections::HashSet::new();
    if node.kind() == "for_statement" {
        if let Some(iter) = find_child_of_kind(node, "iterator") {
            for i in 0..iter.child_count() {
                if let Some(c) = iter.child(i) {
                    if c.kind() == "identifier" {
                        out.insert(node_text(c, source).to_string());
                    }
                }
            }
        }
    }
    let mut cursor = node.walk();
    for child in node.children(&mut cursor) {
        if child.kind() == "function_definition" || child.kind() == "lambda" {
            continue;
        }
        if child.is_named() {
            out.extend(collect_loop_index_vars(child, source));
        }
    }
    out
}
```

