/// Find the nearest enclosing method (a `function_definition` inside a
/// `methods` block) of a node.
pub(crate) fn enclosing_method(node: Node) -> Option<Node> {
    let mut current = node.parent();
    while let Some(p) = current {
        if p.kind() == "function_definition" {
            return Some(p);
        }
        if p.kind() == "class_definition" || p.kind() == "source_file" {
            return None;
        }
        current = p.parent();
    }
    None
}
