pub(crate) fn first_call_argument_is(node: Node, name: &str, source: &str) -> bool {
    let args = match find_child_of_kind(node, "arguments") {
        Some(a) => a,
        None => return false,
    };
    let mut cursor = args.walk();
    for child in args.children(&mut cursor) {
        if child.is_named() {
            return child.kind() == "identifier" && node_text(child, source) == name;
        }
    }
    false
}
