    pub(crate) fn check_adproplc(&self, node: Node, source: &str) -> Vec<Diagnostic> {
        if !self.is_check_enabled("ADPROPLC") || node.kind() != "identifier" {
            return Vec::new();
        }
        let Some(class) = enclosing_class_definition(node) else {
            return Vec::new();
        };
        if !is_app_designer_class(class, source) || !method_has_self_param(node, "app", source) {
            return Vec::new();
        }
        let name = node_text(node, source);
        if !collect_class_property_names(class, source).contains(name) {
            return Vec::new();
        }
        // Skip the correct `app.X` form, assignment targets (ADPROP), and
        // function-name identifiers.
        if let Some(parent) = node.parent() {
            match parent.kind() {
                "field_expression" => return Vec::new(),
                "assignment" => {
                    if parent
                        .child_by_field_name("left")
                        .map(|l| l.id() == node.id())
                        .unwrap_or(false)
                    {
                        return Vec::new();
                    }
                }
                "function_call" => {
                    if parent
                        .child_by_field_name("name")
                        .map(|n| n.id() == node.id())
                        .unwrap_or(false)
