            }
        }
        let pos = node.start_position();
        vec![Diagnostic {
            rule_id: "ADPROPLC",
            message: format!("Use app.{name} to reference a property of app."),
            severity: Severity::Warning,
            byte_range: node.start_byte()..node.end_byte(),
            line: pos.row + 1,
            column: pos.column + 1,
            fix: None,
