use super::*;

impl GoodPracticesEngine {
    /// PFRIN / PFRUS: PARFOR reduction-variable checks.
    pub(crate) fn check_parfor_reduction(&self, tree: &tree_sitter::Tree, source: &str) -> Vec<Diagnostic> {
        let any_enabled = self.is_check_enabled("PFRIN") || self.is_check_enabled("PFRUS");
        if !any_enabled {
            return Vec::new();
        }
        let sym = SymbolTable::build(tree, source);
        let mut diagnostics = Vec::new();
        for parfor in collect_parfor_nodes(tree.root_node(), source) {
            let Some(body) = find_child_of_kind(parfor, "block") else { continue };
            let mut seen = std::collections::HashSet::new();
            let mut assignments = Vec::new();
            collect_nodes_of_kind(body, "assignment", &mut assignments);
            for assign in assignments {
                let Some(lhs) = assign.child_by_field_name("left") else { continue };
                if lhs.kind() != "identifier" { continue; }
                let name = node_text(lhs, source).to_string();
                let rhs = assign.child_by_field_name("right");
                let is_reduction = match rhs {
                    Some(r) if r.kind() == "binary_operator" => r
                        .child_by_field_name("left")
                        .or_else(|| r.child(0))
                        .map(|l| l.kind() == "identifier" && node_text(l, source) == name.as_str())
                        .unwrap_or(false),
                    _ => false,
                };
                if !is_reduction || !seen.insert(name.clone()) { continue; }
                if self.is_check_enabled("PFRIN")
                    && !is_defined_before_parfor(&sym, &name, parfor.start_byte())
                {
                    let pos = lhs.start_position();
                    diagnostics.push(Diagnostic {
                        rule_id: "PFRIN",
                        message: format!("The reduction variable {name} might not be set before the PARFOR loop."),
                        severity: Severity::Warning,
                        byte_range: lhs.start_byte()..lhs.end_byte(),
                        line: pos.row + 1,
                        column: pos.column + 1,
                        fix: None,
                    });
                }
                if self.is_check_enabled("PFRUS") {
                    let uses = uses_after_parfor(&sym, &name, parfor.end_byte(), tree, false);
                    if uses.is_empty() {
                        let pos = lhs.start_position();
                        diagnostics.push(Diagnostic {
                            rule_id: "PFRUS",
                            message: format!("The reduction variable {name} might not be used after the PARFOR loop."),
                            severity: Severity::Warning,
                            byte_range: lhs.start_byte()..lhs.end_byte(),
                            line: pos.row + 1,
                            column: pos.column + 1,
                            fix: None,
                        });
                    }
                }
            }
        }
        diagnostics
    }
}
